    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.swCalprmAxisEClass, source, new String[]{"documentation", "This element specifies an individual input parameter axis (abscissa)."});
        this.addAnnotation((ENamedElement)this.getSwCalprmAxis_SwAxisIndex(), source, new String[]{"documentation", "This attribute specifies which axis is specified by the containing SwCalprmAxis.\r\n\r\nFor example in a curve this is usually \"1\". In a map this is \"1\" or \"2\"."});
        this.addAnnotation((ENamedElement)this.getSwCalprmAxis_Category(), source, new String[]{"documentation", "This property specifies the category of a particular axis."});
        this.addAnnotation((ENamedElement)this.getSwCalprmAxis_SwCalprmAxisTypeProps(), source, new String[]{"documentation", "specific properties depending on the type of the axis."});
        this.addAnnotation((ENamedElement)this.getSwCalprmAxis_SwCalibrationAccess(), source, new String[]{"documentation", "Describes the applicability of parameters and variables. "});
        this.addAnnotation((ENamedElement)this.getSwCalprmAxis_DisplayFormat(), source, new String[]{"documentation", "This property specifies how the axis values shall be displayed e.g. in documents or in measurement and calibration tools."});
        this.addAnnotation((ENamedElement)this.getSwCalprmAxis_BaseType(), source, new String[]{"documentation", "The SwBaseType to be used for the axis. Note that this is not applicable for ApplicationDataTypes. The value shall be ignored."});
        this.addAnnotation((ENamedElement)this.swCalprmAxisTypePropsEClass, source, new String[]{"documentation", "Base class for the type of the calibration axis. This provides the particular model of the specialization. If the specialization would be the directly from SwCalPrmAxis, the sequence of common properties and the specializes ones would be different."});
        this.addAnnotation((ENamedElement)this.swCalprmAxisSetEClass, source, new String[]{"documentation", "This element specifies the input parameter axes (abscissas) of parameters (and variables, if these are used adaptively)."});
        this.addAnnotation((ENamedElement)this.getSwCalprmAxisSet_SwCalprmAxis(), source, new String[]{"documentation", "One axis belonging to this SwCalprmAxisSet"});
        this.addAnnotation((ENamedElement)this.swCalprmValueAxisLabelsEClass, source, new String[]{"documentation", "This element is used to record textual descriptions of axis values and is contained in ASAP1.4, for reasons of backward compatibility.\r\n\r\nIn new systems, the application should be implemented via conversion formulae."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum, source, new String[]{"documentation", "This enum specifies the possible values of the category property within  SwCalprmAxis."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "STD_AXIS means that input and output axis definition are stored within this CURVE.\r\nThere is no shared or calculated axis."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "STD-AXIS means that input and output axis definition are stored within this CURVE.\r\nThere is no shared or calculated axis. This value is obsolete."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "FIX_AXIS means that the input axis is not stored. The axis is calculated using parameters  and so on it is also not possible to modify the axis points."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(3), source, new String[]{"documentation", "FIX-AXIS means that the input axis is not stored. The axis is calculated using parameters  and so on it is also not possible to modify the axis points. This value is obsolete."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(4), source, new String[]{"documentation", "CURVE_AXIS uses a separate CURVE to rescale the axis. The referenced CURVE is used to lookup an axis index, and the index value is used by the controller to determine the operating point in the CURVE or MAP."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(5), source, new String[]{"documentation", "CURVE-AXIS uses a separate CURVE to rescale the axis. The referenced CURVE is used to lookup an axis index, and the index value is used by the controller to determine the operating point in the CURVE or MAP. This value is obsolete."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(6), source, new String[]{"documentation", "COM_AXIS is equal to an STD_AXIS, the difference is, that a COM_AXIS is an shared axis, that means this axis can be used multiple times by different curves or maps."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(7), source, new String[]{"documentation", "COM-AXIS is equal to an STD_AXIS, the difference is, that a COM-AXIS is an shared axis, that means this axis can be used multiple times by different curves or maps. This value is obsolete."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(8), source, new String[]{"documentation", "RES_AXIS is also an shared axis like COM_AXIS, the difference is that this kind of axis can be used for rescaling."});
        this.addAnnotation((ENamedElement)this.calprmAxisCategoryEnumEEnum.getELiterals().get(9), source, new String[]{"documentation", "RES-AXIS is also an shared axis like COM_AXIS, the difference is that this kind of axis can be used for rescaling. This value is obsolete."});
    }

